import math
from sys import stdin

def modAdd(x, mod):
    return x - ((x // mod) * mod)

def ModAdd(a, b, p):
    return modAdd((a + b) % p, p)

def ModMul(a, b, p):
    return modAdd(a * b % p, p) % p

def ModInv(a, p):
    return modAdd(pow(a, p - 2, p), p)

def add(a, b, p):
    return (a + b) % p

def mul(a, b, p):
    return (a * b) % p

def query(a, l, r, p, modAdd, ModAdd, ModMul, ModInv, add, mul):
    ans = 0
    for i in range(l - 1, r):
        for j in range(l - 1, r):
            ans += ModMul(a[i] % p, ans % p, p)
    return ans

def sum_with_query(a, queries, p, modAdd, ModAdd, ModMul, ModInv, add, mul):
    for l, r in queries:
        ModAdd, ModMul, ModInv, add = modAdd, ModMul, ModInv, add
        ans = query(a, l, r, p, modAdd, ModAdd, ModMul, ModInv, add, mul)
    return ans

def main():
    n, m, p = map(int, stdin.readline().strip().split())
    a = list(map(int, stdin.readline().strip().split()))
    queries = [map(int, stdin.readline().strip().split()) for _ in range(m)]
    result = sum_with_query(a, queries, p, modAdd, ModAdd, ModMul, ModInv, add, mul)
