from collections import defaultdict

def build_tree():
    # Function to build a tree based on input nodes
    nodes = input().strip().split()
    n, m = int(nodes[0]), int(nodes[1] if len(nodes) == 2 else 0)
    edges = []
    for _ in range(m + 2):
        nodes = input().strip().split()
        # Only build edges for black nodes as the path must have at least one diameter with alternating colors
        if nodes[0] == '1' and nodes[2] == '1':
            edges.append([int(nodes[1]) - 1, int(nodes[3]) - 1])
        elif nodes[0] == '0' and nodes[2] == '0':
            edges.append([int(nodes[1]) - 1, int(nodes[3]) - 1])
    return nodes, edges

def is_valid_tree(nodes, edges):
    # Check if a tree can be constructed with alternating colors
    node_count = len(nodes)
    node_colors = defaultdict(lambda: 0)
    black_count = 0
    for i, node in enumerate(nodes):
        if int(node) == 1:  # Mark as black
            if black_count >= 2:
                return False
            black_count += 1
        node_colors[int(node)] += 1

    if black_count == 0:
        return False
    if black_count == node_count:
        return False

    # Vertices inside the last diameter must have different colors if their nodes are on this diameter
    if black_count == 1:
        last_node = edges[-1][0] if len(edges[-1]) == 2 else -1
        if last_node != -1 and node_colors[last_node] != node_colors[-1]:
            return True
        else:
            return False
    else:
        # Return True if the last node has the opposite color to the first node
        if node_colors[-1] == black_count:
            return True
        return False

def solve(n, b, w):
    nodes = list(range(n)) + ['0'] * w
    edges = []
    for _ in range(n + b):
        nodes.append(input().strip())

    if w < n:
        print(-1, file=sys.stdout)
        return

    while edges:
        for i, edge in enumerate(edges):
            u, v = edge[0], edge[1]
            nodes[u] = nodes[u][1]
            nodes[v] = nodes[v][1]
            edges[i][0], edges[i][1] = nodes[u], nodes[v]

        if is_valid_tree(nodes, edges):
            return str(nodes[:b]).replace(' ', ''), '\n'.join(map(str, edges))

    return -1

if __name__ == "__main__":
    t = int(input())
    for _ in range(t):
        n, b = map(int, input().split())
        print(*solve(n, b, 0), sep='\n')
