from math import gcd

# Initialize the modulo value
MOD = 10**9 + 7

# Function to calculate the modular inverse using Fermat's Little Theorem
def modular_inverse(x):
    return pow(x, MOD - 2, MOD)

# Function to calculate the next term in the series
def f_next(r, n):
    if r == 0:
        return 1  # Base case: fr(0) = 1 for all r
    # Using Euler's Totient Function to calculate f0
    phi = n
    for d in range(2, n + 1):
        if gcd(d, n) == 1:
            phi -= phi // d
    # Return f0(n) * phi mod MOD
    return 1 + phi * f0(r - 1) % MOD

# Function to calculate f0(n) for 0 <= r <= 10^6
def f0(n):
    if n == 1:
        return 1

    # Using Euler's Totient Function to count co-primes
    count = 0
    for i in range(1, n + 1):
        if gcd(i, n) == 1:
            count += 1

    return count % MOD

