def riffle_and_expand(N, K):
    @lru_cache(maxsize=None)
    def helper(i, n):
        if i == n:
            return [i]
        return [i] + helper(i + 1, n) + helper(i + n, n)

    result = []
    for _ in range(K + 1):
        result.extend(helper(1, N))
    return result

