from itertools import permutations

def construct_tree(B, W):
    if B == 0 and W == 0:
        return None

    colors = ['B' if i % 2 == 0 else 'W' for i in range(B + W)]
    acceptable_trees = []

    for color_perm in permutations(colors):
        path = [color_perm[B + 1] * 2]

        for i in range(B):
            path.append(color_perm[i] * 2)
            path.append(color_perm[i + B] * 2)

        if all(color_perm[j] != color_perm[j + 1] for j in range(len(color_perm) - 1)):
            acceptable_trees.append((path, color_perm.index('B'), color_perm.index('W')))

    if acceptable_trees:
        _, _, diameter_index = min(acceptable_trees, key=lambda x: get_diameter(x[0]))
        return path[diameter_index]
    else:
        return -1

def get_diameter(path):
    B, W = path.count('B'), path.count('W')
    path = list(path)
    for i in range(B + W - 2):
        if path[i] != path[i + 2]:
            return i + 1
    return len(path) - 1

def main():
    T = int(input().strip())

    for _ in range(T):
        B, W = map(int, input().strip().split())
        print(construct_tree(B, W))

