from collections import defaultdict

def order_diameter(parent, child):
    diameter = 0
    while child:
        parent[child] += 1
        child = parent[child]
        diameter += child
    return diameter - 1

def find_diameter(tree, parent):
    count = defaultdict(int)
    result = []
    for node in tree:
        parent_delta = order_diameter(parent, node)
        count[parent_delta] += 1
        for v in tree[node]:
            if count[v] % 2 == 0:
                continue
            result.append((parent_delta, v))
    return result

def construct_tree(black, white, tree):
    parent = [-1 for _ in range(black + white + 1)]
    for i, (node1, node2) in enumerate(tree):
        parent[node1] = node2
    result = find_diameter(tree, parent)
    for n1, n2 in result:
        if n2 > n1:
            tree[n1 + 1], tree[n2 + 1] = n2, n1
        if n2 == black - white + 1 and parent[n2] == black + white:
            return tree, n2
    return tree, -1

def find_min_diameter(black, white):
    trees = {}
    for i in range(black + white):
        trees[i] = {}
        for _ in range(2):
            ti, tree = construct_tree(black, white, trees[i])
            if ti in trees:
                tree[0: len(trees[ti])] = tree
