class Spices:
    def __init__(self):
        self.prime_factors = {}
        self.prime_factorizations = {}

    def add_factor(self, prime, exponent):
        if prime not in self.prime_factors:
            self.prime_factors[prime] = 1
            self.prime_factorizations[prime] = []
        self.prime_factors[prime] = max(self.prime_factors[prime], exponent)
        self.prime_factorizations[prime].append(exponent)

    def highest_common_factor(self, primes):
        factors = set(prime for prime in primes if prime in self.prime_factors)
        for prime in factors:
            yield max(exponent for exponent in self.prime_factorizations[prime] if exponent > 0)

    def lcm(self, other):
        lcm = 1
        for prime, min_ext in zip(self.prime_factors.keys(), other.prime_factors.values()):
