def riffle_sort(N, K):
    # Initialize the sorted array
    sorted_array = list(range(1, N + 1))
    # Perform K riffle shuffles
    for _ in range(K):
        # Merge the sorted array and an initial unsorted array
        merged = sorted_array[:]
        unsorted = [i for i in range(1, N, 2)] + unsorted
        # Perform the riffle operation
        for i in range(N):
            if unsorted[i] % 2 == 0:
                sorted_array[i] = unsorted[i] + sorted_array[i]
            else:
                sorted_array[i] = merged[i]
    return tuple(sorted_array)

