    """Calculate D(n), the number of integers between 1 and n with exactly 4 divisors."""
    count = 0
    for k in range(1, n + 1):
        if k == 1 or k * k > n:
            count += count_divisors(k)
            if k > 1 and k * k < n and count_divisors(k * k) == 4:
                count += count_divisors(k * k)
    return count

n = int(input())
print(D(n))
